(* ---- Machine and head encoding ---- *)

Import ListNotations.
Open Scope list_scope.
Open Scope string_scope.

Definition tm := Eval compute in (TM_from_str "1RB1RE_1LC0RA_1LD0LC_0RA1RF_0RD---_1RC1RA").

Fixpoint bits (s:string) : list Sym :=
  match s with
  | EmptyString => []
  | String a s' =>
      (if Nat.eqb (nat_of_ascii a) 48 then 0 else 1) :: bits s'
  end.

Inductive head_name :=
| hnHash | hnHash1 | hnHashE | hnHash00
| hnDollar | hnAt | hnAtP.

Definition head_denote h : DH0*DH0 :=
  match h with
  | hnHash => ((A,<[1;0]),(C,[0;0]))
  | hnHash1 => ((E,<[1;0;1]),(C,[0;0]))
  | hnHashE => ((A,<[1;0]),(C,[0;0;0;0;0;0;0;1;0;1]))
  | hnHash00 => ((A,<[1;0]),(C,[0;0;0;0]))
  | hnDollar => ((A,<[1;1;1]),(C,[0;0]))
  | hnAt => ((A,<[1;0;0]),(C,[0;0]))
  | hnAtP => ((A,<[1;0;0]),(C,[0;0;0;1;0;1;0;0;1]))
  end.

Notation hHash := (head_denote hnHash).
Notation hHash1 := (head_denote hnHash1).
Notation hHashE := (head_denote hnHashE).
Notation hHash00 := (head_denote hnHash00).
Notation hDollar := (head_denote hnDollar).
Notation hAt := (head_denote hnAt).
Notation hAtP := (head_denote hnAtP).

Notation hash := [hHash].
Notation hash1 := [hHash1].
Notation hashE := [hHashE].
Notation hash00 := [hHash00].
Notation dollar := [hDollar].
Notation atSignal := [hAt].
Notation atP := [hAtP].

Record checked_rule := mk_checked_rule {
  rule_input : head_name;
  rule_output : list head_name;
  rule_before : string;
  rule_after : string
}.

Definition rule_inputs r : list (DH0*DH0) :=
  [head_denote (rule_input r)].
Definition rule_outputs r : list (DH0*DH0) :=
  map head_denote (rule_output r).
Definition rule_top r : list Sym := bits (rule_before r).
Definition rule_bottom r : list Sym := bits (rule_after r).

Definition checked_rule_validb r : bool :=
  segRLs_n1_c tm (rule_inputs r) (rule_outputs r)
    (rule_top r) (rule_bottom r) 100000.

Lemma checked_rule_valid r:
  checked_rule_validb r = true ->
  segRLs_n tm (rule_inputs r) (rule_outputs r)
    (rule_top r) (rule_bottom r) 1.
Proof.
  apply segRLs_n1_c_spec.
Qed.

