Lemma all_super_io_correct:
  map super_rule_io all_super_rules = all_super_io.
Proof. native_check_eq. Qed.

Definition default_super_rule :=
  mk_checked_rule hnHash [] EmptyString EmptyString.

Lemma all_super_rules_checked:
  forallb checked_rule_validb all_super_rules = true.
Proof. native_check_eq. Qed.

Lemma all_super_rule_valid r:
  In r all_super_rules ->
  segRLs_n tm (rule_inputs r) (rule_outputs r)
    (rule_top r) (rule_bottom r) 1.
Proof.
  intro Hr. apply checked_rule_valid.
  exact ((proj1 (forallb_forall checked_rule_validb all_super_rules)
    all_super_rules_checked) r Hr).
Qed.

(* ---- Column programs ---- *)

Import ListNotations.
Open Scope list.
Open Scope string_scope.

Definition super_rule_at n : checked_rule :=
  nth n all_super_rules default_super_rule.

Definition super_io_at n : head_name * list head_name :=
  nth n all_super_io (hnHash, []).

Lemma super_io_at_spec i:
  super_io_at i = super_rule_io (super_rule_at i).
Proof.
  unfold super_io_at. rewrite <- all_super_io_correct.
  change (nth i (map super_rule_io all_super_rules)
    (super_rule_io default_super_rule) =
    super_rule_io (super_rule_at i)).
  rewrite map_nth. reflexivity.
Qed.

Definition atom_inputs i : list (DH0*DH0) :=
  [head_denote (fst (super_io_at i))].
Definition atom_outputs i : list (DH0*DH0) :=
  map head_denote (snd (super_io_at i)).

Lemma atom_io_spec i:
  atom_inputs i = rule_inputs (super_rule_at i) /\
  atom_outputs i = rule_outputs (super_rule_at i).
Proof.
  split.
  - unfold atom_inputs, rule_inputs. rewrite super_io_at_spec.
    unfold super_rule_io. reflexivity.
  - unfold atom_outputs, rule_outputs. rewrite super_io_at_spec.
    unfold super_rule_io. reflexivity.
Qed.

Inductive column_program :=
| PAtom (rule:nat)
| PThen (left right:column_program)
| PRepeat (rule extra:nat).

Fixpoint PSequence (first:column_program) (rest:list column_program) :=
  match rest with
  | [] => first
  | p::rest' => PThen first (PSequence p rest')
  end.

Fixpoint program_inputs p : list (DH0*DH0) :=
  match p with
  | PAtom i => atom_inputs i
  | PThen p1 p2 => program_inputs p1 ++ program_inputs p2
  | PRepeat i n => (atom_inputs i)^^(S n)
  end.

Fixpoint program_outputs p : list (DH0*DH0) :=
  match p with
  | PAtom i => atom_outputs i
  | PThen p1 p2 => program_outputs p1 ++ program_outputs p2
  | PRepeat i n => (atom_outputs i)^^(S n)
  end.

Fixpoint program_top p : string :=
  match p with
  | PAtom i => rule_before (super_rule_at i)
  | PThen p1 _ => program_top p1
  | PRepeat i _ => rule_before (super_rule_at i)
  end.

Fixpoint program_bottom p : string :=
  match p with
  | PAtom i => rule_after (super_rule_at i)
  | PThen _ p2 => program_bottom p2
  | PRepeat i _ => rule_after (super_rule_at i)
  end.

Fixpoint program_okb p : bool :=
  match p with
  | PAtom i => Nat.ltb i (length all_super_rules)
  | PThen p1 p2 =>
      program_okb p1 && program_okb p2 &&
      String.eqb (program_bottom p1) (program_top p2)
  | PRepeat i _ =>
      Nat.ltb i (length all_super_rules) &&
      String.eqb (rule_before (super_rule_at i))
        (rule_after (super_rule_at i))
  end.

Lemma super_rule_at_valid i:
  Nat.ltb i (length all_super_rules) = true ->
  segRLs_n tm (atom_inputs i)
    (atom_outputs i)
    (rule_top (super_rule_at i)) (rule_bottom (super_rule_at i)) 1.
Proof.
  rewrite Nat.ltb_lt. intro Hi.
  destruct (atom_io_spec i) as [Hin Hout]. rewrite Hin,Hout.
  apply all_super_rule_valid, nth_In. exact Hi.
Qed.

Lemma repeat_super_rule_valid i n:
  Nat.ltb i (length all_super_rules) = true ->
  rule_before (super_rule_at i) = rule_after (super_rule_at i) ->
  segRLs_n tm
    ((atom_inputs i)^^(S n))
    ((atom_outputs i)^^(S n))
    (rule_top (super_rule_at i)) (rule_bottom (super_rule_at i)) 1.
Proof.
  intros Hi Heq. unfold rule_top, rule_bottom in *. induction n.
  - cbn [lpow]. rewrite !app_nil_r.
    apply super_rule_at_valid. exact Hi.
  - rewrite !lpow_S.
    eapply segRLs_n_trans.
    + apply super_rule_at_valid. exact Hi.
    + rewrite lpow_S in IHn.
      unfold rule_bottom.
      rewrite <- Heq at 1.
      exact IHn.
    + lia.
    + lia.
Qed.

Lemma column_program_valid p:
  program_okb p = true ->
  segRLs_n tm (program_inputs p) (program_outputs p)
    (bits (program_top p)) (bits (program_bottom p)) 1.
Proof.
  induction p as [i|p1 IH1 p2 IH2|i n]; cbn [program_okb program_inputs
      program_outputs program_top program_bottom]; intro H.
  - apply super_rule_at_valid. exact H.
  - apply andb_true_iff in H as [H12 Heq].
    apply andb_true_iff in H12 as [H1 H2].
    apply String.eqb_eq in Heq.
    eapply segRLs_n_trans.
    + exact (IH1 H1).
    + rewrite Heq. exact (IH2 H2).
    + lia.
    + lia.
  - apply andb_true_iff in H as [Hi Heq].
    apply String.eqb_eq in Heq.
    apply repeat_super_rule_valid; assumption.
Qed.

(* ---- Signal run-length encoding ---- *)

Import ListNotations.
Open Scope list.

Definition head_name_eqb (x y:head_name) : bool :=
  match x,y with
  | hnHash,hnHash | hnHash1,hnHash1 | hnHashE,hnHashE
  | hnHash00,hnHash00 | hnDollar,hnDollar | hnAt,hnAt
  | hnAtP,hnAtP => true
  | _,_ => false
  end.

Lemma head_name_eqb_eq x y:
  head_name_eqb x y = true <-> x=y.
Proof. destruct x,y; cbn; intuition congruence. Qed.

Fixpoint signal_rle_eval (runs:list (head_name*nat)) : list (DH0*DH0) :=
  match runs with
  | [] => []
  | (h,n)::runs' => ([head_denote h]^^n) ++ signal_rle_eval runs'
  end.

Definition signal_rle_push h n runs :=
  match runs with
  | [] => [(h,n)]
  | (h',m)::runs' =>
      if head_name_eqb h h' then (h,n+m)::runs'
      else (h,n)::runs
  end.

Fixpoint signal_rle_norm runs :=
  match runs with
  | [] => []
  | (h,n)::runs' => signal_rle_push h n (signal_rle_norm runs')
  end.

Inductive signal_piece :=
| SPLit (h:head_name)
| SPRun (h:head_name) (n:nat).

Fixpoint signal_raw_eval pieces : list (DH0*DH0) :=
  match pieces with
  | [] => []
  | SPLit h::pieces' => head_denote h :: signal_raw_eval pieces'
  | SPRun h n::pieces' =>
      ([head_denote h]^^n) ++ signal_raw_eval pieces'
  end.

Fixpoint signal_pieces_runs pieces : list (head_name*nat) :=
  match pieces with
  | [] => []
  | SPLit h::pieces' => (h,1%nat)::signal_pieces_runs pieces'
  | SPRun h n::pieces' => (h,n)::signal_pieces_runs pieces'
  end.

Lemma signal_raw_eval_rle pieces:
  signal_raw_eval pieces = signal_rle_eval (signal_pieces_runs pieces).
Proof.
  induction pieces as [|[h|h n] pieces IH]; cbn in *;
    rewrite ?IH; reflexivity.
Qed.

Lemma signal_rle_push_sound h n runs:
  signal_rle_eval (signal_rle_push h n runs) =
  ([head_denote h]^^n) ++ signal_rle_eval runs.
Proof.
  destruct runs as [|[h' m] runs]; cbn [signal_rle_push signal_rle_eval].
  - rewrite app_nil_r. reflexivity.
  - destruct (head_name_eqb h h') eqn:E.
    + apply head_name_eqb_eq in E; subst h'.
      cbn [signal_rle_eval].
      rewrite lpow_add,List.app_assoc. reflexivity.
    + reflexivity.
Qed.

Lemma signal_rle_norm_sound runs:
  signal_rle_eval (signal_rle_norm runs) = signal_rle_eval runs.
Proof.
  induction runs as [|[h n] runs IH]; [reflexivity|].
  cbn [signal_rle_norm signal_rle_eval].
  rewrite signal_rle_push_sound,IH. reflexivity.
Qed.

