(* ---- Middle-column stream ---- *)

Import ListNotations.
Open Scope list.

Inductive middle_phase :=
| mpLead | mpJ3 | mpJ4 | mpR1First
| mpR1 (round:nat) | mpR2 (round:nat)
| mpR3 (round:nat) | mpR0 (round:nat).

Record middle_state := mk_middle_state {
  middle_q : nat;
  middle_at : middle_phase
}.

Definition middle_next s : middle_state :=
  let q := middle_q s in
  match middle_at s with
  | mpLead => mk_middle_state q mpJ3
  | mpJ3 => mk_middle_state q mpJ4
  | mpJ4 => mk_middle_state q mpR1First
  | mpR1First => mk_middle_state q (mpR2 O)
  | mpR1 k => mk_middle_state q (mpR2 (S k))
  | mpR2 k => mk_middle_state q (mpR3 k)
  | mpR3 k => mk_middle_state q (mpR0 k)
  | mpR0 k => mk_middle_state q (mpR1 k)
  end.

Definition middle_program (machine:nat) s : column_program :=
  let q := middle_q s in
  match machine, middle_at s, q with
  | 16%nat, mpLead, O => tm16_lead_q0
  | 16%nat, mpLead, S q' => tm16_lead_qpos q'
  | 16%nat, mpJ3, O => tm16_q0_j3
  | 16%nat, mpJ3, S q' => tm16_qpos_j3 q'
  | 16%nat, mpJ4, O => tm16_q0_j4
  | 16%nat, mpJ4, S q' => tm16_qpos_j4 q'
  | 16%nat, mpR1First, _ => tm16_cycle_r1_first q
  | 16%nat, mpR1 k, _ => tm16_cycle_r1 q k
  | 16%nat, mpR2 k, _ => tm16_cycle_r2 q k
  | 16%nat, mpR3 k, _ => tm16_cycle_r3 q k
  | 16%nat, mpR0 k, _ => tm16_cycle_r0 q k
  | 17%nat, mpLead, O => tm17_lead_q0
  | 17%nat, mpLead, S q' => tm17_lead_qpos q'
  | 17%nat, mpJ3, O => tm17_q0_j3
  | 17%nat, mpJ3, S q' => tm17_qpos_j3 q'
  | 17%nat, mpJ4, O => tm17_q0_j4
  | 17%nat, mpJ4, S q' => tm17_qpos_j4 q'
  | 17%nat, mpR1First, _ => tm17_cycle_r1_first q
  | 17%nat, mpR1 k, _ => tm17_cycle_r1 q k
  | 17%nat, mpR2 k, _ => tm17_cycle_r2 q k
  | 17%nat, mpR3 k, _ => tm17_cycle_r3 q k
  | 17%nat, mpR0 k, _ => tm17_cycle_r0 q k
  | _, _, _ => tm16_lead_q0
  end.

Lemma middle_program_ok machine s:
  machine = 16%nat \/ machine = 17%nat ->
  program_okb (middle_program machine s) = true.
Proof.
  intros [Hm|Hm]; subst machine; destruct s as [q p]; destruct p; destruct q;
    cbn [middle_program]; apply tm16_lead_q0_ok ||
    apply tm16_lead_qpos_ok || apply tm16_q0_j3_ok ||
    apply tm16_qpos_j3_ok || apply tm16_q0_j4_ok ||
    apply tm16_qpos_j4_ok || apply tm16_cycle_r1_first_ok ||
    apply tm16_cycle_r1_ok || apply tm16_cycle_r2_ok ||
    apply tm16_cycle_r3_ok || apply tm16_cycle_r0_ok ||
    apply tm17_lead_q0_ok || apply tm17_lead_qpos_ok ||
    apply tm17_q0_j3_ok || apply tm17_qpos_j3_ok ||
    apply tm17_q0_j4_ok || apply tm17_qpos_j4_ok ||
    apply tm17_cycle_r1_first_ok || apply tm17_cycle_r1_ok ||
    apply tm17_cycle_r2_ok || apply tm17_cycle_r3_ok ||
    apply tm17_cycle_r0_ok.
Qed.

Lemma middle_program_link machine s:
  machine = 16%nat \/ machine = 17%nat ->
  program_bottom (middle_program machine s) =
  program_top (middle_program machine (middle_next s)).
Proof.
  intros [Hm|Hm]; subst machine; destruct s as [q p]; destruct p; destruct q;
    native_compute; reflexivity.
Qed.

Lemma middle_inputs_nonempty machine s:
  machine = 16%nat \/ machine = 17%nat ->
  program_inputs (middle_program machine s) <> [].
Proof.
  intros [Hm|Hm]; subst machine; destruct s as [q p]; destruct p; destruct q;
    native_compute; discriminate.
Qed.

Lemma middle_outputs_nonempty machine s:
  machine = 16%nat \/ machine = 17%nat ->
  program_outputs (middle_program machine s) <> [].
Proof.
  intros [Hm|Hm]; subst machine; destruct s as [q p]; destruct p; destruct q;
    native_compute; discriminate.
Qed.

Section ChunkStream.
  Context {S A:Type}.
  Variable chunk_head:S->A.
  Variable chunk_tail:S->list A.
  Variable next:S->S.

  CoFixpoint chunk_stream (s:S) (pending:list A) : Stream A :=
    match pending with
    | x::xs => x >> chunk_stream s xs
    | [] => chunk_head s >> chunk_stream (next s) (chunk_tail s)
    end.

  Definition generated_stream s := chunk_stream s [].

  Lemma stream_eq (a b:Stream A):
    Streams.hd a = Streams.hd b ->
    Streams.tl a = Streams.tl b -> a=b.
  Proof. destruct a,b; cbn; congruence. Qed.

  Lemma chunk_stream_pending s xs:
    chunk_stream s xs = xs *> generated_stream s.
  Proof.
    induction xs as [|x xs IH].
    - reflexivity.
    - rewrite (Cons_unfold _ (chunk_stream s (x::xs))) at 1.
      cbn. rewrite IH. reflexivity.
  Qed.

  Lemma generated_stream_unfold s:
    generated_stream s =
      (chunk_head s::chunk_tail s) *> generated_stream (next s).
  Proof.
    apply stream_eq.
    - change (chunk_head s = chunk_head s). reflexivity.
    - change (chunk_stream (next s) (chunk_tail s) =
        chunk_tail s *> generated_stream (next s)).
      apply chunk_stream_pending.
  Qed.
End ChunkStream.

Definition middle_input_stream machine s : Stream (DH0*DH0) :=
  generated_stream
    (fun s => hd hHash (program_inputs (middle_program machine s)))
    (fun s => tl (program_inputs (middle_program machine s))) middle_next s.

Lemma middle_input_unfold machine s (Hm:machine=16%nat \/ machine=17%nat):
  middle_input_stream machine s =
  program_inputs (middle_program machine s) *>
    middle_input_stream machine (middle_next s).
Proof.
  unfold middle_input_stream at 1.
  rewrite generated_stream_unfold.
  destruct (program_inputs (middle_program machine s)) as [|x xs] eqn:E.
  - exfalso. apply (middle_inputs_nonempty machine s Hm). exact E.
  - reflexivity.
Qed.

Definition middle_start q := mk_middle_state q mpLead.

(* ---- Right-edge model ---- *)

Import ListNotations.
Open Scope list.
Open Scope string_scope.

Definition wordX : list Sym := bits "01010100".
Definition end_side n : side := wordX^^n *> ([1] *> 0inf).

Lemma hash_X:
  segRLs_n tm hash hash wordX wordX 1.
Proof.
  unfold wordX; cbn [bits]. solve_segRLs_n1.
Qed.

Lemma hash_end:
  sideRLs tm hash ([1] *> 0inf) (wordX *> ([1] *> 0inf)).
Proof.
  change (sideRLs tm hash ([1] *> const s0)
    ((wordX ++ [1]) *> const s0)).
  apply BoundedConfig.sideRLs_c_spec with (T:=1000).
  vm_check_eq.
Qed.

Lemma hash_tail n:
  sideRLs tm hash (end_side n) (end_side (S n)).
Proof.
  unfold end_side. induction n.
  - exact hash_end.
  - rewrite !lpow_S. apply (proj2 hash_X). exact IHn.
Qed.

Lemma hashes_tail k n:
  sideRLs tm (hash^^k) (end_side n) (end_side (n+k)).
Proof.
  revert n. induction k; intro n.
  - cbn [lpow]. replace (n+0) with n by lia. constructor.
  - rewrite lpow_S. eapply sideRLs_trans.
    + exact (hash_tail n).
    + replace (n+S k) with (S n+k) by lia. exact (IHk (S n)).
Qed.

Record checked_edge_rule := mk_checked_edge_rule {
  edge_input : head_name;
  edge_take_X : nat;
  edge_leave_X : nat;
  edge_hashes : nat;
  edge_before : string;
  edge_after : string
}.

Definition edge_rule_inputs r : list (DH0*DH0) :=
  [head_denote (edge_input r)].
Definition edge_rule_outputs r : list (DH0*DH0) := hash^^(edge_hashes r).
Definition edge_rule_top r : list Sym :=
  bits (edge_before r) ++ wordX^^(edge_take_X r).
Definition edge_rule_bottom r : list Sym :=
  bits (edge_after r) ++ wordX^^(edge_leave_X r).

Definition checked_edge_rule_validb r :=
  segRLs_n1_c tm (edge_rule_inputs r) (edge_rule_outputs r)
    (edge_rule_top r) (edge_rule_bottom r) 100000.

Lemma checked_edge_rule_valid r:
  checked_edge_rule_validb r = true ->
  segRLs_n tm (edge_rule_inputs r) (edge_rule_outputs r)
    (edge_rule_top r) (edge_rule_bottom r) 1.
Proof. apply segRLs_n1_c_spec. Qed.

