Lemma all_edge_effects_correct:
  map edge_effect all_edge_rules = all_edge_effects.
Proof. native_check_eq. Qed.

Definition default_edge_rule :=
  mk_checked_edge_rule hnHash 0 0 0 EmptyString EmptyString.

Lemma all_edge_rules_checked:
  forallb checked_edge_rule_validb all_edge_rules = true.
Proof. native_check_eq. Qed.

(* ---- Right-edge programs ---- *)

Import ListNotations.
Open Scope list.
Open Scope string_scope.

Definition edge_side (prefix:string) n : side :=
  bits prefix *> end_side n.

Definition edge_rule_at n : checked_edge_rule :=
  nth n all_edge_rules default_edge_rule.

Lemma edge_side_split prefix a b:
  edge_side prefix (a+b) =
  (bits prefix ++ wordX^^a) *> end_side b.
Proof.
  unfold edge_side, end_side. rewrite lpow_add.
  repeat rewrite Str_app_assoc. reflexivity.
Qed.

Definition edge_effect_at i : nat*(nat*nat) :=
  nth i all_edge_effects (O,(O,O)).

Lemma edge_effect_at_spec i:
  edge_effect_at i = edge_effect (edge_rule_at i).
Proof.
  unfold edge_effect_at. rewrite <- all_edge_effects_correct.
  change (nth i (map edge_effect all_edge_rules)
    (edge_effect default_edge_rule) = edge_effect (edge_rule_at i)).
  rewrite map_nth. reflexivity.
Qed.

Definition edge_apply_rule i n : option nat :=
  let '(take,(leave,hashes)) := edge_effect_at i in
  if Nat.leb take n then
    Some (leave + (n-take) + hashes)
  else None.

Lemma edge_checked_side r n:
  checked_edge_rule_validb r = true ->
  edge_take_X r <= n ->
  sideRLs tm (edge_rule_inputs r)
    (edge_side (edge_before r) n)
    (edge_side (edge_after r)
      (edge_leave_X r + (n-edge_take_X r) + edge_hashes r)).
Proof.
  intros Hvalid Hle.
  pose proof (checked_edge_rule_valid r Hvalid) as [_ Hrun].
  specialize (Hrun (end_side (n-edge_take_X r))
    (end_side ((n-edge_take_X r)+edge_hashes r))
    (hashes_tail (edge_hashes r) (n-edge_take_X r))).
  unfold edge_rule_top, edge_rule_bottom in Hrun.
  rewrite <- edge_side_split in Hrun.
  rewrite <- edge_side_split in Hrun.
  replace (edge_take_X r+(n-edge_take_X r)) with n in Hrun by lia.
  replace (edge_leave_X r+((n-edge_take_X r)+edge_hashes r))
    with (edge_leave_X r+(n-edge_take_X r)+edge_hashes r) in Hrun by lia.
  exact Hrun.
Qed.

Lemma edge_rule_at_valid i:
  Nat.ltb i (length all_edge_rules) = true ->
  checked_edge_rule_validb (edge_rule_at i) = true.
Proof.
  rewrite Nat.ltb_lt. intro Hi.
  exact ((proj1 (forallb_forall checked_edge_rule_validb all_edge_rules)
    all_edge_rules_checked) _ (nth_In all_edge_rules default_edge_rule Hi)).
Qed.

Lemma edge_atom_side i n n':
  Nat.ltb i (length all_edge_rules) = true ->
  edge_apply_rule i n = Some n' ->
  sideRLs tm (edge_rule_inputs (edge_rule_at i))
    (edge_side (edge_before (edge_rule_at i)) n)
    (edge_side (edge_after (edge_rule_at i)) n').
Proof.
  intros Hi Happly. unfold edge_apply_rule in Happly.
  rewrite edge_effect_at_spec in Happly. unfold edge_effect in Happly.
  destruct (Nat.leb_spec0 (edge_take_X (edge_rule_at i)) n);
    [inversion Happly; subst|discriminate].
  apply edge_checked_side; [apply edge_rule_at_valid; exact Hi|assumption].
Qed.

Inductive edge_program :=
| EAtom (rule:nat) (input:head_name) (take leave hashes:nat)
| EThen (left right:edge_program)
| ERepeat (rule:nat) (input:head_name) (extra:nat).

Fixpoint ESequence (first:edge_program) (rest:list edge_program) :=
  match rest with
  | [] => first
  | p::rest' => EThen first (ESequence p rest')
  end.

Fixpoint edge_program_inputs p : list (DH0*DH0) :=
  match p with
  | EAtom _ input _ _ _ => [head_denote input]
  | EThen p1 p2 => edge_program_inputs p1 ++ edge_program_inputs p2
  | ERepeat _ input n => ([head_denote input])^^(S n)
  end.

Fixpoint edge_program_before p : string :=
  match p with
  | EAtom i _ _ _ _ => edge_before (edge_rule_at i)
  | EThen p1 _ => edge_program_before p1
  | ERepeat i _ _ => edge_before (edge_rule_at i)
  end.

Fixpoint edge_program_after p : string :=
  match p with
  | EAtom i _ _ _ _ => edge_after (edge_rule_at i)
  | EThen _ p2 => edge_program_after p2
  | ERepeat i _ _ => edge_after (edge_rule_at i)
  end.

Definition edge_head_eqb x y :=
  match x,y with
  | hnHash,hnHash | hnHash1,hnHash1 | hnHashE,hnHashE
  | hnHash00,hnHash00 | hnDollar,hnDollar | hnAt,hnAt
  | hnAtP,hnAtP => true
  | _,_ => false
  end.

Lemma edge_head_eqb_eq x y: edge_head_eqb x y = true <-> x=y.
Proof. destruct x,y; cbn; intuition congruence. Qed.

Fixpoint edge_program_okb p : bool :=
  match p with
  | EAtom i input take leave hashes =>
      Nat.ltb i (length all_edge_rules) &&
      edge_head_eqb input (edge_input (edge_rule_at i)) &&
      match edge_effect_at i with
      | (take', (leave', hashes')) =>
          Nat.eqb take take' && Nat.eqb leave leave' &&
          Nat.eqb hashes hashes'
      end
  | EThen p1 p2 =>
      edge_program_okb p1 && edge_program_okb p2 &&
      String.eqb (edge_program_after p1) (edge_program_before p2)
  | ERepeat i input _ =>
      Nat.ltb i (length all_edge_rules) &&
      edge_head_eqb input (edge_input (edge_rule_at i)) &&
      Nat.eqb (edge_take_X (edge_rule_at i)) 0 &&
      Nat.eqb (edge_leave_X (edge_rule_at i)) 0 &&
      Nat.eqb (edge_hashes (edge_rule_at i)) 1 &&
      String.eqb (edge_before (edge_rule_at i))
        (edge_after (edge_rule_at i))
  end.

Fixpoint edge_program_eval p n : option nat :=
  match p with
  | EAtom _ _ take leave hashes =>
      if Nat.leb take n then Some (leave+(n-take)+hashes) else None
  | EThen p1 p2 =>
      match edge_program_eval p1 n with
      | Some n1 => edge_program_eval p2 n1
      | None => None
      end
  | ERepeat _ _ extra => Some (n+S extra)
  end.

Lemma edge_eval_step take leave hashes current next:
  take <= current ->
  leave+(current-take)+hashes = next ->
  (if Nat.leb take current then
     Some (leave+(current-take)+hashes) else None) = Some next.
Proof.
  intros Hle ->. replace (Nat.leb take current) with true by
    (symmetry; apply Nat.leb_le; exact Hle).
  reflexivity.
Qed.

Lemma edge_repeat_side i extra n:
  Nat.ltb i (length all_edge_rules) = true ->
  edge_take_X (edge_rule_at i) = O ->
  edge_leave_X (edge_rule_at i) = O ->
  edge_hashes (edge_rule_at i) = S O ->
  edge_before (edge_rule_at i) = edge_after (edge_rule_at i) ->
  sideRLs tm ((edge_rule_inputs (edge_rule_at i))^^(S extra))
    (edge_side (edge_before (edge_rule_at i)) n)
    (edge_side (edge_after (edge_rule_at i)) (n+S extra)).
Proof.
  intros Hi Htake Hleave Hhash Hword. revert n.
  induction extra; intro n.
  - cbn [lpow]. rewrite !app_nil_r.
    replace (n+1) with (S n) by lia.
    apply edge_atom_side with (n':=S n); [exact Hi|].
    unfold edge_apply_rule. rewrite edge_effect_at_spec.
    unfold edge_effect. rewrite Htake,Hleave,Hhash.
    replace (Nat.leb 0 n) with true by (symmetry; apply Nat.leb_le; lia).
    cbn. f_equal; lia.
  - rewrite lpow_S. eapply sideRLs_trans.
    + apply edge_atom_side with (n':=S n); [exact Hi|].
      unfold edge_apply_rule. rewrite edge_effect_at_spec.
      unfold edge_effect. rewrite Htake,Hleave,Hhash.
      replace (Nat.leb 0 n) with true by (symmetry; apply Nat.leb_le; lia).
      cbn. f_equal; lia.
    + pose proof (IHextra (S n)) as Hnext. rewrite Hword in Hnext.
      replace (n+S (S extra)) with (S n+S extra) by lia.
      exact Hnext.
Qed.

Lemma edge_program_side p n n':
  edge_program_okb p = true ->
  edge_program_eval p n = Some n' ->
  sideRLs tm (edge_program_inputs p)
    (edge_side (edge_program_before p) n)
    (edge_side (edge_program_after p) n').
Proof.
  revert n n'. induction p as [i input take leave hashes|p1 IH1 p2 IH2|i input extra];
    intros n n' Hok Heval; cbn [edge_program_okb edge_program_eval
      edge_program_inputs edge_program_before edge_program_after] in *.
  - apply andb_true_iff in Hok as [Hih Heffects].
    apply andb_true_iff in Hih as [Hi Hinput].
    apply edge_head_eqb_eq in Hinput. subst input.
    destruct (edge_effect_at i) as [take' [leave' hashes']] eqn:E.
    cbn in Heffects. apply andb_true_iff in Heffects as [Htl Hhash].
    apply andb_true_iff in Htl as [Htake Hleave].
    apply Nat.eqb_eq in Htake. apply Nat.eqb_eq in Hleave.
    apply Nat.eqb_eq in Hhash. subst take' leave' hashes'.
    eapply edge_atom_side; [exact Hi|].
    unfold edge_apply_rule. rewrite E. exact Heval.
  - apply andb_true_iff in Hok as [H12 Hword].
    apply andb_true_iff in H12 as [H1 H2].
    apply String.eqb_eq in Hword.
    destruct (edge_program_eval p1 n) as [n1|] eqn:E1; [|discriminate].
    eapply sideRLs_trans.
    + exact (IH1 n n1 H1 E1).
    + rewrite Hword. exact (IH2 n1 n' H2 Heval).
  - apply andb_true_iff in Hok as [H12345 Hword].
    apply andb_true_iff in H12345 as [H1234 Hhash].
    apply andb_true_iff in H1234 as [H123 Hleave].
    apply andb_true_iff in H123 as [H12 Htake].
    apply andb_true_iff in H12 as [Hi Hinput].
    apply edge_head_eqb_eq in Hinput. subst input.
    apply String.eqb_eq in Hword.
    apply Nat.eqb_eq in Htake. apply Nat.eqb_eq in Hleave.
    apply Nat.eqb_eq in Hhash.
    inversion Heval; subst n'.
    eapply edge_repeat_side; eauto.
Qed.

