Definition edge_cycle_program (delta q:nat) : edge_program :=
  ESequence (edge_phase0) [
    ERepeat 9 hnHash (16+delta+17*q);
    edge_phase1;
    ERepeat 37 hnHash (11+delta+17*q);
    edge_phase2;
    ERepeat 75 hnHash (9+delta+17*q);
    edge_phase3;
    ERepeat 126 hnHash (5+delta+17*q);
    edge_phase4
].

Lemma edge_cycle_program_ok delta q:
  edge_program_okb (edge_cycle_program delta q) = true.
Proof. native_check_eq. Qed.

(* ---- Right-edge cycle ---- *)

Import ListNotations.
Open Scope list.
Open Scope string_scope.

Definition edge_parameter (delta q:nat) : nat :=
  34*q*q + 94*q + 65 + delta*(4*q+6).

Definition edge_prefix : string :=
  "00010100010101010101000101000010100".

Definition birth_superword : string :=
  "0101010101000101000101000001010100010101000101010001010100010101010101010100010101000101010001010100010101000101010001010100010101000101010001010101010001010001010100010101000101010001010100010101010101010100101000101000001010000010100000101000001010000010100000101".

Lemma edge_cycle_before delta q:
  edge_program_before (edge_cycle_program delta q) = edge_prefix.
Proof. native_check_eq. Qed.

Lemma edge_cycle_after delta q:
  edge_program_after (edge_cycle_program delta q) =
  String.append birth_superword edge_prefix.
Proof. native_check_eq. Qed.

Lemma bits_append x y:
  bits (String.append x y) = (bits x ++ bits y)%list.
Proof. induction x; cbn; [reflexivity|rewrite IHx; reflexivity]. Qed.

Lemma edge_cycle_growth delta q:
  edge_side (edge_program_after (edge_cycle_program delta q))
      (edge_parameter delta (S q)) =
  bits birth_superword *>
    edge_side (edge_program_before (edge_cycle_program delta q))
      (edge_parameter delta (S q)).
Proof.
  rewrite edge_cycle_before, edge_cycle_after.
  unfold edge_side. rewrite bits_append, Str_app_assoc. reflexivity.
Qed.

Lemma edge_parameter_step delta q:
  edge_parameter delta (S q) =
  edge_parameter delta q + 128 + 4*delta + 68*q.
Proof. unfold edge_parameter; lia. Qed.

Lemma edge_cycle_eval delta q:
  edge_program_eval (edge_cycle_program delta q)
    (edge_parameter delta q) =
  Some (edge_parameter delta (S q)).
Proof.
  cbn [edge_cycle_program ESequence edge_program_eval].
  rewrite edge_phase0_eval by (unfold edge_parameter; lia).
  cbn [edge_program_eval].
  rewrite edge_phase1_eval by (unfold edge_parameter; lia).
  cbn [edge_program_eval].
  rewrite edge_phase2_eval by (unfold edge_parameter; lia).
  cbn [edge_program_eval].
  rewrite edge_phase3_eval by (unfold edge_parameter; lia).
  cbn [edge_program_eval].
  rewrite edge_phase4_eval by lia.
  f_equal. rewrite edge_parameter_step. lia.
Qed.

Lemma edge_cycle_side delta q:
  sideRLs tm (edge_program_inputs (edge_cycle_program delta q))
    (edge_side (edge_program_before (edge_cycle_program delta q))
      (edge_parameter delta q))
    (edge_side (edge_program_after (edge_cycle_program delta q))
      (edge_parameter delta (S q))).
Proof.
  eapply edge_program_side.
  - apply edge_cycle_program_ok.
  - apply edge_cycle_eval.
Qed.

(* ---- Adjacent-column flows ---- *)

