Lemma signal_raw_eval_app xs ys:
  signal_raw_eval (xs++ys) = signal_raw_eval xs ++ signal_raw_eval ys.
Proof.
  induction xs as [|[h|h n] xs IH]; cbn;
    rewrite ?IH, ?List.app_assoc; reflexivity.
Qed.

