(* ---- Infinite column flow ---- *)

Import ListNotations.
Open Scope list.

Definition ms q p := mk_middle_state q p.
Definition hashes31 := hash^^31.

Definition lagged_stream machine q p : Stream (DH0*DH0) :=
  hashes31 *> middle_input_stream machine (ms (S q) p).

Definition right_r3 machine q := lagged_stream machine q mpJ3.
Definition right_r2_early machine q :=
  program_outputs (middle_program machine (ms q (mpR2 O))) *>
    right_r3 machine q.
Definition right_r1_early machine q :=
  program_outputs (middle_program machine (ms q mpR1First)) *>
    right_r2_early machine q.
Definition right_j4 machine q :=
  program_outputs (middle_program machine (ms q mpJ4)) *>
    right_r1_early machine q.
Definition right_j3 machine q :=
  program_outputs (middle_program machine (ms q mpJ3)) *>
    right_j4 machine q.
Definition right_lead machine q :=
  program_outputs (middle_program machine (ms q mpLead)) *>
    right_j3 machine q.

Definition middle_right_stream machine s : Stream (DH0*DH0) :=
  let q := middle_q s in
  match middle_at s with
  | mpLead => right_lead machine q
  | mpJ3 => right_j3 machine q
  | mpJ4 => right_j4 machine q
  | mpR1First => right_r1_early machine q
  | mpR2 O => right_r2_early machine q
  | mpR3 O => lagged_stream machine q mpJ3
  | mpR0 O => lagged_stream machine q mpJ4
  | mpR1 O => lagged_stream machine q mpR1First
  | mpR2 (S k) => lagged_stream machine q (mpR2 k)
  | mpR3 (S k) => lagged_stream machine q (mpR3 k)
  | mpR0 (S k) => lagged_stream machine q (mpR0 k)
  | mpR1 (S k) => lagged_stream machine q (mpR1 k)
  end.

Ltac finish_lagged flow Hm :=
  unfold middle_right_stream, lagged_stream, ms, hashes31;
  cbn [middle_at middle_q middle_next middle_program];
  rewrite (middle_input_unfold _ _ Hm);
  cbn [middle_at middle_q middle_next middle_program];
  rewrite <- Str_app_assoc;
  rewrite flow;
  rewrite Str_app_assoc;
  reflexivity.

Lemma machine16_ok : 16%nat=16%nat \/ 16%nat=17%nat.
Proof. left; reflexivity. Qed.
Lemma machine17_ok : 17%nat=16%nat \/ 17%nat=17%nat.
Proof. right; reflexivity. Qed.

Lemma middle_right_unfold machine s
    (Hm:machine=16%nat \/ machine=17%nat):
  middle_right_stream machine s =
  program_outputs (middle_program machine s) *>
    middle_right_stream machine (middle_next s).
Proof.
  destruct Hm as [Hm|Hm]; subst machine; destruct s as [q p]; destruct p;
    cbn [middle_right_stream right_lead right_j3 right_j4
      right_r1_early right_r2_early right_r3 lagged_stream ms middle_next];
    try reflexivity.
  - destruct round.
    + finish_lagged (tm16_flow_r1_first q) machine16_ok.
    + finish_lagged (tm16_flow_r1_shift q round) machine16_ok.
  - destruct round.
    + reflexivity.
    + finish_lagged (tm16_flow_r2_shift q round) machine16_ok.
  - destruct round.
    + finish_lagged (tm16_flow_r3_first q) machine16_ok.
    + finish_lagged (tm16_flow_r3_shift q round) machine16_ok.
  - destruct round.
    + finish_lagged (tm16_flow_r0_first q) machine16_ok.
    + finish_lagged (tm16_flow_r0_shift q round) machine16_ok.
  - destruct round.
    + finish_lagged (tm17_flow_r1_first q) machine17_ok.
    + finish_lagged (tm17_flow_r1_shift q round) machine17_ok.
  - destruct round.
    + reflexivity.
    + finish_lagged (tm17_flow_r2_shift q round) machine17_ok.
  - destruct round.
    + finish_lagged (tm17_flow_r3_first q) machine17_ok.
    + finish_lagged (tm17_flow_r3_shift q round) machine17_ok.
  - destruct round.
    + finish_lagged (tm17_flow_r0_first q) machine17_ok.
    + finish_lagged (tm17_flow_r0_shift q round) machine17_ok.
Qed.

Lemma middle_downRect_canonical machine s
    (Hm:machine=16%nat \/ machine=17%nat):
  downRect tm (middle_input_stream machine s)
    (middle_right_stream machine s)
    (bits (program_top (middle_program machine s))) 1.
Proof.
  eapply segRLs_n_inf_trans with
    (P:=fun L R top => exists s,
      L = middle_input_stream machine s /\
      R = middle_right_stream machine s /\
      top = bits (program_top (middle_program machine s))).
  - intros L R top [s0 [-> [-> ->]]].
    exists (program_inputs (middle_program machine s0)),
      (program_outputs (middle_program machine s0)),
      (bits (program_bottom (middle_program machine s0))),
      (middle_input_stream machine (middle_next s0)),
      (middle_right_stream machine (middle_next s0)).
    split.
    + destruct (program_outputs (middle_program machine s0)) as [|h hs] eqn:E.
      * exfalso. apply (middle_outputs_nonempty machine s0 Hm). exact E.
      * cbn; lia.
    + split.
      * apply middle_input_unfold. exact Hm.
      * split.
        -- apply middle_right_unfold. exact Hm.
        -- split.
           ++ apply column_program_valid, middle_program_ok. exact Hm.
           ++ exists (middle_next s0). repeat split; try reflexivity.
              rewrite <- middle_program_link; [reflexivity|exact Hm].
  - exists s. repeat split; reflexivity.
Qed.

Lemma middle_right_start_splice16 q:
  middle_right_stream 16 (middle_start q) =
  edge_program_inputs (edge_cycle_program 0 q) *>
    middle_input_stream 16 (middle_start (S q)).
Proof.
  destruct q as [|q].
  - rewrite (middle_input_unfold 16 (middle_start 1) machine16_ok).
    unfold middle_right_stream, middle_start, right_lead, right_j3,
      right_j4, right_r1_early, right_r2_early, right_r3,
      lagged_stream, ms, hashes31.
    cbn [middle_q middle_at middle_program middle_next].
    repeat rewrite <- Str_app_assoc.
    f_equal.
  - rewrite (middle_input_unfold 16 (middle_start (S (S q))) machine16_ok).
    unfold middle_right_stream, middle_start, right_lead, right_j3,
      right_j4, right_r1_early, right_r2_early, right_r3,
      lagged_stream, ms, hashes31.
    cbn [middle_q middle_at middle_program middle_next].
    repeat rewrite <- Str_app_assoc.
    f_equal. repeat rewrite <- List.app_assoc.
    exact (tm16_edge_splice_qpos q).
Qed.

Lemma middle_right_start_splice17 q:
  middle_right_stream 17 (middle_start q) =
  edge_program_inputs (edge_cycle_program 1 q) *>
    middle_input_stream 17 (middle_start (S q)).
Proof.
  destruct q as [|q].
  - rewrite (middle_input_unfold 17 (middle_start 1) machine17_ok).
    unfold middle_right_stream, middle_start, right_lead, right_j3,
      right_j4, right_r1_early, right_r2_early, right_r3,
      lagged_stream, ms, hashes31.
    cbn [middle_q middle_at middle_program middle_next].
    repeat rewrite <- Str_app_assoc.
    f_equal.
  - rewrite (middle_input_unfold 17 (middle_start (S (S q))) machine17_ok).
    unfold middle_right_stream, middle_start, right_lead, right_j3,
      right_j4, right_r1_early, right_r2_early, right_r3,
      lagged_stream, ms, hashes31.
    cbn [middle_q middle_at middle_program middle_next].
    repeat rewrite <- Str_app_assoc.
    f_equal. repeat rewrite <- List.app_assoc.
