(* ---- Infinite right rectangle ---- *)

Import ListNotations.
Open Scope list.

Definition dynamic_side_step tm0
    (P : Stream (DH0*DH0) -> side -> Prop)
    (L : Stream (DH0*DH0)) (top : side) : Prop :=
  exists hs Ltail Ledge top' w width,
    0 < width /\
    w <> [] /\
    L = hs *> Ltail /\
    sideRLs tm0 hs top (w *> top') /\
    downRect tm0 Ltail Ledge w width /\
    P Ledge top'.

Lemma dynamic_side_unbounded tm0 P L top:
  (forall L0 top0, P L0 top0 -> dynamic_side_step tm0 P L0 top0) ->
  P L top ->
  quadRect tm0 L top.
Proof.
  intros Hstep HP.
  unfold quadRect, InfiniteRectInternal.quadRect.
  assert (Hn : forall n L0 top0, P L0 top0 ->
      @InfiniteRectInternal.sideS_n tm0 L0 top0 n).
  {
    induction n as [|n IH]; intros L0 top0 HP0.
    - apply InfiniteRectInternal.sideS_n_0.
    - destruct (Hstep _ _ HP0) as
        (hs & Ltail & Ledge & top' & w & width &
         Hwidth & Hw & HL & Hedge & Hrect & HP').
      specialize (IH _ _ HP').
      unfold downRect, InfiniteRectInternal.downRect in Hrect.
      specialize (Hrect top' n IH).
      eapply InfiniteRectInternal.sideS_n_mono.
      + rewrite HL.
        eapply InfiniteRectInternal.sideS_n_app_right;
          [exact Hedge|exact Hrect].
      + lia.
  }
  intros n; eapply Hn; eauto.
Qed.

Lemma birth_top16 q:
  bits birth_superword =
  bits (program_top (middle_program 16 (middle_start (S q)))).
Proof. native_check_eq. Qed.

Lemma birth_top17 q:
  bits birth_superword =
  bits (program_top (middle_program 17 (middle_start (S q)))).
Proof. native_check_eq. Qed.

Definition right_cycle16 (L:Stream (DH0*DH0)) (top:side) : Prop :=
  exists q,
    L = middle_right_stream 16 (middle_start q) /\
    top = edge_side edge_prefix (edge_parameter 0 q).

Definition right_cycle17 (L:Stream (DH0*DH0)) (top:side) : Prop :=
  exists q,
    L = middle_right_stream 17 (middle_start q) /\
    top = edge_side edge_prefix (edge_parameter 1 q).

Lemma edge_cycle_emits delta q:
  sideRLs tm (edge_program_inputs (edge_cycle_program delta q))
    (edge_side edge_prefix (edge_parameter delta q))
    (bits birth_superword *>
      edge_side edge_prefix (edge_parameter delta (S q))).
Proof.
  rewrite <- (edge_cycle_before delta q).
  rewrite <- (edge_cycle_growth delta q).
  apply edge_cycle_side.
Qed.

Lemma right_cycle16_step L top:
  right_cycle16 L top -> dynamic_side_step tm right_cycle16 L top.
Proof.
  intros [q [-> ->]].
  exists (edge_program_inputs (edge_cycle_program 0 q)),
    (middle_input_stream 16 (middle_start (S q))),
    (middle_right_stream 16 (middle_start (S q))),
    (edge_side edge_prefix (edge_parameter 0 (S q))),
    (bits birth_superword), 1%nat.
  repeat split.
  - lia.
  - cbn [birth_superword bits]; discriminate.
  - apply middle_right_start_splice16.
  - apply edge_cycle_emits.
  - rewrite (birth_top16 q). apply middle_downRect_canonical, machine16_ok.
  - exists (S q). split; reflexivity.
Qed.

Lemma right_cycle17_step L top:
  right_cycle17 L top -> dynamic_side_step tm right_cycle17 L top.
Proof.
  intros [q [-> ->]].
  exists (edge_program_inputs (edge_cycle_program 1 q)),
    (middle_input_stream 17 (middle_start (S q))),
    (middle_right_stream 17 (middle_start (S q))),
    (edge_side edge_prefix (edge_parameter 1 (S q))),
    (bits birth_superword), 1%nat.
  repeat split.
  - lia.
  - cbn [birth_superword bits]; discriminate.
  - apply middle_right_start_splice17.
  - apply edge_cycle_emits.
  - rewrite (birth_top17 q). apply middle_downRect_canonical, machine17_ok.
  - exists (S q). split; reflexivity.
Qed.

Lemma tm16_right_quadRect:
  quadRect tm (middle_right_stream 16 (middle_start 0))
    (edge_side edge_prefix (edge_parameter 0 0)).
Proof.
  eapply dynamic_side_unbounded with (P:=right_cycle16).
  - apply right_cycle16_step.
  - exists 0%nat. split; reflexivity.
Qed.

Lemma tm17_right_quadRect:
  quadRect tm (middle_right_stream 17 (middle_start 0))
    (edge_side edge_prefix (edge_parameter 1 0)).
Proof.
  eapply dynamic_side_unbounded with (P:=right_cycle17).
  - apply right_cycle17_step.
  - exists 0%nat. split; reflexivity.
Qed.

Lemma tm16_full_quadRect:
  quadRect tm (middle_input_stream 16 (middle_start 0))
    (bits (program_top (middle_program 16 (middle_start 0))) *>
      edge_side edge_prefix (edge_parameter 0 0)).
Proof.
  eapply downRect_quadRect_concat.
  - apply middle_downRect_canonical, machine16_ok.
  - apply tm16_right_quadRect.
Qed.

Lemma tm17_full_quadRect:
  quadRect tm (middle_input_stream 17 (middle_start 0))
    (bits (program_top (middle_program 17 (middle_start 0))) *>
      edge_side edge_prefix (edge_parameter 1 0)).
Proof.
  eapply downRect_quadRect_concat.
  - apply middle_downRect_canonical, machine17_ok.
  - apply tm17_right_quadRect.
Qed.

(* ---- Left-edge primitives ---- *)

Import ListNotations.
Open Scope string_scope.
Open Scope list.

Definition head_link (left right:head_name) : DH0*DH0 :=
  (snd (head_denote left), fst (head_denote right)).

Notation lHH := (head_link hnHash hnHash).
Notation lHD := (head_link hnHash hnDollar).
Notation lDH := (head_link hnDollar hnHash).
Notation lHE := (head_link hnHash hnHashE).
Notation lEH := (head_link hnHashE hnHash).
Notation lH00 := (head_link hnHash hnHash00).
Notation l00H := (head_link hnHash00 hnHash).
Notation lH1 := (head_link hnHash hnHash1).
Notation l1H := (head_link hnHash1 hnHash).
Notation lHP := (head_link hnHash hnAtP).
Notation lP1 := (head_link hnAtP hnHash1).

Definition second_links_even j :=
  [l1H] ++ ([lHH]^^(4*j+14)).
Definition second_links_odd j :=
  [lP1;l1H] ++ ([lHH]^^(4*j+14)).

Ltac es_v3_TL ::= constr:(1000).

Definition partial_left (near far:string) n : side :=
  rev (bits near) *> ([1;0]^^n *> (rev (bits far) *> 0inf)).

Definition cut_A16 n := partial_left "11010111101011" "10" (n+2).
Definition cut_C16 n := partial_left "11010101110" "1010" (n-1).
Definition cut_B16 n := partial_left "11010101110101011" "101010" (n-2).

Definition cut_A17 n :=
  partial_left "1101011110101110101011" "10" (n+2).
Definition cut_C17 n :=
  partial_left "1101010111010101110" "101010" (n-2).
Definition cut_B17 n :=
  partial_left "1101010111010101110101011" "10101010" (n-3).

(* The middle programs cut a temporal column immediately after the first
   hash of each outer packet.  At that cut the current signal is dollar. *)
Definition dollar_cut16 n :=
  partial_left "011101011111010" "1010" n.
Definition dollar_cut17 n :=
  partial_left "01110101111101011111010" "101010" (n-1).

Lemma tm16_open_column n:
  sideRLs (flip tm) [lHD] (cut_A16 n) (dollar_cut16 n).
Proof.
  unfold cut_A16, dollar_cut16, partial_left, head_link.
  cbn [head_denote]. es' n.
Qed.

Lemma tm17_open_column x:
  sideRLs (flip tm) [lHH;lHD]
    (cut_A17 (1+x)) (dollar_cut17 (1+x)).
Proof.
  unfold cut_A17, dollar_cut17, partial_left, head_link.
  cbn [head_denote]. replace (1+x-1) with x by lia. es' x.
Qed.

Lemma tm17_open_column_ge n:
  1 <= n ->
  sideRLs (flip tm) [lHH;lHD] (cut_A17 n) (dollar_cut17 n).
Proof.
  intro Hn. replace n with (1+(n-1)) by lia. apply tm17_open_column.
Qed.

Definition left_hash_state (far near:string) a b : side :=
  rev (bits near) *>
    ([1;0]^^b *> ([0;1]^^a *> (rev (bits far) *> 0inf))).

Lemma left_hash_run (state:nat->nat->side)
    (Hshift:forall a b, sideRLs (flip tm) [lHH]
      (state a (1+b)) (state (1+a) b)) a b:
  sideRLs (flip tm) ([lHH]^^b) (state a b) (state (a+b) 0%nat).
Proof.
  revert a. induction b as [|b IH]; intro a.
  - cbn [lpow]. replace (a+0) with a by lia. constructor.
  - rewrite lpow_S. replace (a+S b) with (1+a+b) by lia.
    eapply sideRLs_trans; [apply Hshift|apply IH].
Qed.

(* ---- Checked left-edge phases ---- *)

Import ListNotations.
Open Scope string_scope.
Open Scope list.
Ltac es_v3_TL ::= constr:(1000).

Definition tm16_h3_state a b : side :=
  left_hash_state "101010101010" "01110101111101011" a b.

Lemma tm16_h3_shift a b:
  sideRLs (flip tm) [lHH]
    (tm16_h3_state a (1+b)) (tm16_h3_state (1+a) b).
Proof.
  unfold tm16_h3_state, left_hash_state, head_link.
  cbn [head_denote]. es' a b.
Qed.

Lemma tm16_h3_exit a:
  sideRLs (flip tm) [head_link hnHash hnAtP] (tm16_h3_state a 0)
    (partial_left "11010101110" "1010"
      (a+7)).
Proof.
  unfold tm16_h3_state, left_hash_state, partial_left, head_link.
  cbn [head_denote]. es' a.
Qed.

Lemma tm16_h3_rest_enter x:
  sideRLs (flip tm) [head_link hnDollar hnHash; head_link hnHash hnHash; head_link hnHash hnHash00; head_link hnHash00 hnHash]
    (dollar_cut16 (x+25))
    (tm16_h3_state 0 (x+21)).
Proof.
  unfold dollar_cut16, partial_left, tm16_h3_state, left_hash_state,
    head_link. cbn [head_denote].
  es' x.
Qed.

Lemma tm16_h3_rest_full x:
  sideRLs (flip tm)
    ([head_link hnDollar hnHash; head_link hnHash hnHash; head_link hnHash hnHash00; head_link hnHash00 hnHash] ++ (([lHH]^^(x+21)) ++
      [head_link hnHash hnAtP]))
    (dollar_cut16 (x+25))
    (cut_C16 (x+29)).
Proof.
  refine (@sideRLs_trans (flip tm) [head_link hnDollar hnHash; head_link hnHash hnHash; head_link hnHash hnHash00; head_link hnHash00 hnHash]
    (([lHH]^^(x+21))++[head_link hnHash hnAtP])
    (dollar_cut16 (x+25)) (tm16_h3_state 0 (x+21))
    (cut_C16 (x+29)) _ _).
  - apply tm16_h3_rest_enter.
  - refine (@sideRLs_trans (flip tm) ([lHH]^^(x+21))
      [head_link hnHash hnAtP] (tm16_h3_state 0 (x+21))
      (tm16_h3_state (0+(x+21)) 0)
      (cut_C16 (x+29)) _ _).
    + exact (left_hash_run tm16_h3_state tm16_h3_shift 0 (x+21)).
    + cbn [Nat.add].
      unfold cut_C16.
      replace ((x+29)-1)
        with ((x+21)+7) by lia.
      apply tm16_h3_exit.
Qed.

