(* ---- Left-edge realization ---- *)

Import ListNotations.
Open Scope list.

Definition open_links delta := ([lHH]^^delta) ++ [lHD].
Definition rest_links_r0 j :=
  [lDH;lHH;lHE;lEH] ++ ([lHH]^^(4*j+9)) ++ [lH1].
Definition rest_links_r1 j :=
  [head_link hnDollar hnHash00;l00H] ++
    ([lHH]^^(4*j+11)) ++ [lHP].
Definition rest_links_r2 j :=
  [head_link hnDollar hnHashE;lEH] ++
    ([lHH]^^(4*j+11)) ++ [lH1].
Definition rest_links_r3 j :=
  [lDH;lHH;lH00;l00H] ++ ([lHH]^^(4*j+9)) ++ [lHP].

Definition column_links_r0 delta j :=
  rest_links_r0 j ++ second_links_even j ++ open_links delta.
Definition column_links_r1 delta j :=
  rest_links_r1 j ++ second_links_odd j ++ open_links delta.
Definition column_links_r2 delta j :=
  rest_links_r2 j ++ second_links_even j ++ open_links delta.
Definition column_links_r3 delta j :=
  rest_links_r3 j ++ second_links_odd j ++ open_links delta.

Lemma lcons_head_link a b:
  lcons (fst (head_denote a)) [head_link a b] =
    ([head_denote a], fst (head_denote b)).
Proof. destruct a,b; reflexivity. Qed.

Lemma lcons_hashes n:
  lcons (fst hHash) ([lHH]^^n) = (hash^^n, fst hHash).
Proof.
  induction n as [|n IH]; [reflexivity|].
  rewrite !lpow_S.
  eapply InfiniteRectInternal.lcons_app;
    [apply lcons_head_link|exact IH].
Qed.

Lemma lcons_r0_prefix:
  lcons (fst hDollar) [lDH;lHH;lHE;lEH] =
    ([hDollar;hHash;hHash;hHashE], fst hHash).
Proof. vm_check_eq. Qed.

Lemma lcons_r1_prefix:
  lcons (fst hDollar) [head_link hnDollar hnHash00;l00H] =
    ([hDollar;hHash00], fst hHash).
Proof. vm_check_eq. Qed.

Lemma lcons_r2_prefix:
  lcons (fst hDollar) [head_link hnDollar hnHashE;lEH] =
    ([hDollar;hHashE], fst hHash).
Proof. vm_check_eq. Qed.

Lemma lcons_r3_prefix:
  lcons (fst hDollar) [lDH;lHH;lH00;l00H] =
    ([hDollar;hHash;hHash;hHash00], fst hHash).
Proof. vm_check_eq. Qed.

Lemma lcons_odd_prefix:
  lcons (fst hAtP) [lP1;l1H] =
    ([hAtP;hHash1], fst hHash).
Proof. vm_check_eq. Qed.

Lemma lcons_column_r2 delta j:
  lcons (fst hDollar) (column_links_r2 delta j) =
    ([hDollar;hHashE] ++
      ((hash^^(4*j+11)) ++
      ([hHash] ++ ([hHash1] ++
      ((hash^^(4*j+14)) ++ ((hash^^delta) ++ [hHash]))))),
      fst hDollar).
Proof.
  unfold column_links_r2, rest_links_r2, second_links_even, open_links.
  repeat rewrite <- List.app_assoc.
  eapply InfiniteRectInternal.lcons_app; [apply lcons_r2_prefix|].
  eapply InfiniteRectInternal.lcons_app; [apply lcons_hashes|].
  eapply InfiniteRectInternal.lcons_app; [apply lcons_head_link|].
  eapply InfiniteRectInternal.lcons_app; [apply lcons_head_link|].
  eapply InfiniteRectInternal.lcons_app; [apply lcons_hashes|].
  eapply InfiniteRectInternal.lcons_app; [apply lcons_hashes|].
  apply lcons_head_link.
Qed.

Lemma lpow_snoc {A} (l:list A) n:
  (l^^n) ++ l = l^^(S n).
Proof.
  replace (S n) with (n+1) by lia.
  rewrite lpow_add. cbn [lpow]. rewrite app_nil_r. reflexivity.
Qed.

Lemma fold_hash_left n xs:
  (hash^^n) ++ (hash ++ xs) = (hash^^S n) ++ xs.
Proof. rewrite List.app_assoc, lpow_snoc. reflexivity. Qed.

Lemma fold_hash_tail n m:
  (hash^^n) ++ ((hash^^m) ++ hash) = hash^^(n+S m).
Proof. rewrite lpow_snoc, <- lpow_add. reflexivity. Qed.

Lemma lcons_column_r0 delta j:
  lcons (fst hDollar) (column_links_r0 delta j) =
    ([hDollar;hHash;hHash;hHashE] ++
      ((hash^^(4*j+9)) ++
      ([hHash] ++ ([hHash1] ++
      ((hash^^(4*j+14)) ++ ((hash^^delta) ++ [hHash]))))),
      fst hDollar).
Proof.
  unfold column_links_r0, rest_links_r0, second_links_even, open_links.
  repeat rewrite <- List.app_assoc.
  eapply InfiniteRectInternal.lcons_app; [apply lcons_r0_prefix|].
  eapply InfiniteRectInternal.lcons_app; [apply lcons_hashes|].
  eapply InfiniteRectInternal.lcons_app; [apply lcons_head_link|].
  eapply InfiniteRectInternal.lcons_app; [apply lcons_head_link|].
  eapply InfiniteRectInternal.lcons_app; [apply lcons_hashes|].
  eapply InfiniteRectInternal.lcons_app; [apply lcons_hashes|].
  apply lcons_head_link.
Qed.

