Ltac normalize_phase :=
  unfold rest_links_r0, rest_links_r1, rest_links_r2, rest_links_r3,
    second_links_even, second_links_odd, open_links;
  cbn [lpow];
  repeat match goal with
  | |- context [4 * (4 * ?k + ?r) + ?c] =>
      let n := fresh "n" in
      replace (4*(4*k+r)+c) with (16*k+(4*r+c)) by lia
  end.

