Lemma middle_input_length_pos machine s
    (Hm:machine=16%nat \/ machine=17%nat):
  0 < length (program_inputs (middle_program machine s)).
Proof.
  pose proof (middle_inputs_nonempty machine s Hm) as H.
  destruct (program_inputs (middle_program machine s)); cbn in *;
    [contradiction|lia].
Qed.

Lemma left_program_progress
    (P:DH0 -> Stream (DH0*DH0) -> side -> Prop)
    machine s h l h' ls l'
    (Hm:machine=16%nat \/ machine=17%nat):
  lcons h ls = (program_inputs (middle_program machine s),h') ->
  sideRLs (flip tm) ls l l' ->
  P h' (middle_input_stream machine (middle_next s)) l' ->
  exists hs L' h'' ls' l'',
    0 < length hs /\
    middle_input_stream machine s = hs *> L' /\
    lcons h ls' = (hs,h'') /\
    sideRLs (flip tm) ls' l l'' /\
    P h'' L' l''.
Proof.
  intros Hlcons Hside HP.
  exists (program_inputs (middle_program machine s)),
    (middle_input_stream machine (middle_next s)), h', ls, l'.
  repeat split.
  - apply middle_input_length_pos. exact Hm.
  - apply middle_input_unfold. exact Hm.
  - exact Hlcons.
  - exact Hside.
  - exact HP.
Qed.

Definition state0 p := mk_middle_state 0 p.

Inductive Left16State : DH0 -> Stream (DH0*DH0) -> side -> Prop :=
| L16Lead : Left16State (fst hHash)
    (middle_input_stream 16 (state0 mpLead)) (cut_A16 25)
| L16J3 : Left16State (fst hDollar)
    (middle_input_stream 16 (state0 mpJ3)) (dollar_cut16 25)
| L16J4 : Left16State (fst hDollar)
    (middle_input_stream 16 (state0 mpJ4)) (dollar_cut16 29)
| L16R1First : Left16State (fst hDollar)
    (middle_input_stream 16 (state0 mpR1First)) (dollar_cut16 33)
| L16R2 k : Left16State (fst hDollar)
    (middle_input_stream 16 (state0 (mpR2 k))) (dollar_cut16 (16*k+37))
| L16R3 k : Left16State (fst hDollar)
    (middle_input_stream 16 (state0 (mpR3 k)))
    (dollar_cut16 (16*(S k)+25))
| L16R0 k : Left16State (fst hDollar)
    (middle_input_stream 16 (state0 (mpR0 k)))
    (dollar_cut16 (16*(S k)+29))
| L16R1 k : Left16State (fst hDollar)
    (middle_input_stream 16 (state0 (mpR1 k)))
    (dollar_cut16 (16*(S k)+33)).

Lemma tm16_left_progress h L l:
  Left16State h L l -> exists hs L' h' ls l',
    0 < length hs /\ L = hs *> L' /\
    lcons h ls = (hs,h') /\ sideRLs (flip tm) ls l l' /\
    Left16State h' L' l'.
Proof.
  intro H; destruct H.
  - eapply left_program_progress with (s:=state0 mpLead).
    + left; reflexivity.
    + cbn [state0 middle_program]. exact tm16_lead_lcons.
    + apply tm16_open_column.
    + cbn [state0 middle_next]. constructor.
  - eapply left_program_progress with (s:=state0 mpJ3).
    + left; reflexivity.
    + cbn [state0 middle_program]. exact tm16_q0_j3_lcons.
    + exact (tm16_column_r3 0).
    + cbn [state0 middle_next]. constructor.
  - eapply left_program_progress with (s:=state0 mpJ4).
    + left; reflexivity.
    + cbn [state0 middle_program]. exact tm16_q0_j4_lcons.
    + exact (tm16_column_r0 0).
    + cbn [state0 middle_next]. constructor.
  - eapply left_program_progress with (s:=state0 mpR1First).
    + left; reflexivity.
    + cbn [state0 middle_program]. exact tm16_r1_first_lcons.
    + exact (tm16_column_r1 0).
    + cbn [state0 middle_next]. constructor.
  - eapply left_program_progress with (s:=state0 (mpR2 k)).
    + left; reflexivity.
    + cbn [state0 middle_program]. exact (tm16_r2_lcons k).
    + exact (tm16_column_r2 k).
    + cbn [state0 middle_next].
      replace (16*k+41) with (16*S k+25) by lia. constructor.
  - eapply left_program_progress with (s:=state0 (mpR3 k)).
    + left; reflexivity.
    + cbn [state0 middle_program]. exact (tm16_r3_lcons k).
    + replace (4*k+7) with (4*S k+3) by lia.
      exact (tm16_column_r3 (S k)).
    + cbn [state0 middle_next]. constructor.
  - eapply left_program_progress with (s:=state0 (mpR0 k)).
    + left; reflexivity.
    + cbn [state0 middle_program]. exact (tm16_r0_lcons k).
    + replace (4*k+8) with (4*S k+4) by lia.
      exact (tm16_column_r0 (S k)).
    + cbn [state0 middle_next]. constructor.
  - eapply left_program_progress with (s:=state0 (mpR1 k)).
    + left; reflexivity.
    + cbn [state0 middle_program]. exact (tm16_r1_lcons k).
    + replace (4*k+9) with (4*S k+5) by lia.
      exact (tm16_column_r1 (S k)).
    + cbn [state0 middle_next]. constructor.
Qed.

Lemma tm16_left_realizes:
  leftRealizes tm (fst hHash)
    (middle_input_stream 16 (middle_start 0)) (cut_A16 25).
Proof.
  eapply leftRealizes_inf_concat with (P:=Left16State).
  - apply tm16_left_progress.
  - constructor.
Qed.

