(* ---- Finite initialization ---- *)

(* The chunked evaluator and its specification are the construction from
   Bouncer_v3.  They are repeated here so this proof does not import the
   rest of that machine-specific development. *)
Fixpoint multistep_c' tm0 n1 n2 n3 c :=
  match n1 with
  | O => multistep_c tm0 n3 c
  | S n1' =>
      match multistep_c tm0 n2 c with
      | Some c' => multistep_c' tm0 n1' n2 n3 c'
      | None => None
      end
  end.

Lemma multistep_c'_spec tm0 n1 n2 n3 c c':
  multistep_c' tm0 n1 n2 n3 c = Some c' <->
  c -[tm0]->> (n1*n2+n3) / c'.
Proof.
  revert c c'. induction n1; cbn [multistep_c']; intros.
  - apply multistep_c_spec.
  - destruct (multistep_c tm0 n2 c) eqn:E.
    + apply multistep_c_spec in E. rewrite IHn1.
      replace (S n1*n2+n3) with (n2+(n1*n2+n3)) by lia.
      split; intro H.
      * eapply multistep_trans; eauto.
      * apply rewind_split in H. destruct H as [c0 [H1 H2]].
        multistep_deterministic. exact H2.
    + split; [congruence|].
      replace (S n1*n2+n3) with (n2+(n1*n2+n3)) by lia.
      intro H. apply rewind_split in H. destruct H as [c0 [H1 H2]].
      apply multistep_c_spec in H1. congruence.
Qed.

Lemma indexed_step_nonhalted tm0 c c':
  c -[tm0]-> c' -> ~ halted tm0 c.
Proof.
  unfold halted. intros H Hhalt. inverts H; congruence.
Qed.

Lemma indexed_multistep_nonhalt tm0 n c1 c2:
  c1 -[tm0]->> n / c2 -> ~ halts tm0 c2 -> ~ halts tm0 c1.
Proof.
  revert c1 c2. induction n; intros c1 c2 Hrun Hnonhalt.
  - inversion Hrun; subst. exact Hnonhalt.
  - inversion Hrun; subst.
    specialize (IHn _ _ H1 Hnonhalt).
    intros [n0 [c3 [Hsteps Hhalt]]]. apply IHn.
    destruct n0 as [|n0].
    + inversion Hsteps; subst.
      destruct (indexed_step_nonhalted _ _ _ H0 Hhalt).
    + inversion Hsteps; subst.
      assert (c'=c'0) by (eapply step_deterministic; eauto). subst c'0.
      exists n0,c3. split; assumption.
Qed.

Definition tm16_rectangle : Q * tape :=
  cut_A16 25 {{{ (fst hHash,R) }}}
    (bits (program_top (middle_program 16 (middle_start 0))) *>
      edge_side edge_prefix (edge_parameter 0 0)).

Definition tm17_rectangle : Q * tape :=
  cut_A17 26 {{{ (fst hHash,R) }}}
    (bits (program_top (middle_program 17 (middle_start 0))) *>
      edge_side edge_prefix (edge_parameter 1 0)).

Lemma tm16_rectangle_nonhalt : ~ halts tm tm16_rectangle.
Proof.
  unfold tm16_rectangle.
  eapply quadRect_nonhalt.
  - apply tm16_full_quadRect.
  - apply tm16_left_realizes.
Qed.

Lemma tm17_rectangle_nonhalt : ~ halts tm tm17_rectangle.
Proof.
  unfold tm17_rectangle.
  eapply quadRect_nonhalt.
  - apply tm17_full_quadRect.
  - apply tm17_left_realizes.
Qed.

Lemma tm16_initialization :
  c0 -[tm]->> (529*530+377) / tm16_rectangle.
Proof.
  eapply (proj1 (multistep_c'_spec tm 529 530 377 c0 tm16_rectangle)).
  native_compute. repeat rewrite <-const_unfold. reflexivity.
Qed.

Lemma tm17_initialization :
  (C;;tape0) -[tm]->> (562*563+112) / tm17_rectangle.
Proof.
  eapply (proj1 (multistep_c'_spec tm 562 563 112
    (C;;tape0) tm17_rectangle)).
  native_compute. repeat rewrite <-const_unfold. reflexivity.
Qed.


Theorem nonhalt : ~ halts tm c0.
Proof.
  eapply indexed_multistep_nonhalt.
  - apply tm16_initialization.
  - apply tm16_rectangle_nonhalt.
Qed.

End TM16.

Module TM17.

Definition tm := Eval compute in (TM_from_str "1LB0LA_0RC1RF_1RE1RD_0RB---_1LA0RC_1RA1RC").

Definition to_tm16 q :=
  match q with
  | A => C
  | B => D
  | C => A
  | D => E
  | E => B
  | F => F
  end.

Lemma perm : Perm tm TM16.tm to_tm16.
Proof.
  split.
  - intros [] [] H; native_compute in H |- *; congruence.
  - intros [] [] s' d q' H; native_compute in H |- *;
      inversion H; reflexivity.
Qed.

Lemma canonical_nonhalt : ~ halts TM16.tm (C;;tape0).
Proof.
  eapply TM16.indexed_multistep_nonhalt.
  - apply TM16.tm17_initialization.
  - apply TM16.tm17_rectangle_nonhalt.
Qed.

Theorem nonhalt : ~ halts tm c0.
Proof.
  eapply perm_nonhalt.
  - apply perm.
  - exact canonical_nonhalt.
Qed.

End TM17.

Print Assumptions TM16.nonhalt.
Print Assumptions TM17.nonhalt.
